81	+func discoverCapabilityHelpers(t *testing.T) []capabilityHelper {
82	+	t.Helper()
83	+
84	+	dir := findAgentDir(t)
85	+	fset := token.NewFileSet()
86	+	//nolint:staticcheck // ParseDir intentionally scans every production file regardless of build tags.
87	+	pkgs, err := parser.ParseDir(fset, dir, func(info os.FileInfo) bool {
88	+		return !strings.HasSuffix(info.Name(), "_test.go")
89	+	}, 0)
90	+	if err != nil {
91	+		t.Fatalf("parser.ParseDir(%s): %v", dir, err)
92	+	}
93	+
94	+	var helpers []capabilityHelper
95	+	for _, pkg := range pkgs {
96	+		for _, file := range pkg.Files {
97	+			for _, decl := range file.Decls {
98	+				fn, ok := decl.(*ast.FuncDecl)
99	+				if !ok || fn.Recv != nil || !isCapabilityHelperName(fn.Name.Name) {
100	+					continue
101	+				}
102	+				resolver, capability := capabilityResolver(fn)
103	+				helpers = append(helpers, capabilityHelper{
104	+					function:   fn.Name.Name,
105	+					capability: capability,
106	+					resolver:   resolver,
107	+					position:   fset.Position(fn.Pos()),
108	+				})
109	+			}
110	+		}
111	+	}
112	+	return helpers
