119	+func capabilityResolver(fn *ast.FuncDecl) (string, string) {
120	+	if fn.Body == nil || len(fn.Body.List) != 1 {
121	+		return "", ""
122	+	}
123	+	ret, ok := fn.Body.List[0].(*ast.ReturnStmt)
124	+	if !ok || len(ret.Results) != 1 {
125	+		return "", ""
126	+	}
127	+	call, ok := ret.Results[0].(*ast.CallExpr)
128	+	if !ok {
129	+		return "", ""
130	+	}
131	+
132	+	resolver, typeArg := indexedCall(call.Fun)
133	+	if resolver == nil || typeArg == nil {
134	+		return "", ""
135	+	}
136	+	capability, ok := typeArg.(*ast.Ident)
137	+	if !ok {
138	+		return resolver.Name, ""
139	+	}
140	+	return resolver.Name, capability.Name
141	+}
142	+
143	+func indexedCall(expr ast.Expr) (*ast.Ident, ast.Expr) {
144	+	switch indexed := expr.(type) {
145	+	case *ast.IndexExpr:
146	+		resolver, ok := indexed.X.(*ast.Ident)
147	+		if !ok {
148	+			return nil, nil
149	+		}
150	+		return resolver, indexed.Index
151	+	case *ast.IndexListExpr:
152	+		resolver, ok := indexed.X.(*ast.Ident)
153	+		if !ok || len(indexed.Indices) != 1 {
154	+			return nil, nil
155	+		}
156	+		return resolver, indexed.Indices[0]
157	+	default:
158	+		return nil, nil
159	+	}
160	+}
