162	+// documentedBuiltinCapabilities returns the capabilities listed in the
163	+// DeclaredCaps doc comment, and the subset marked as refusing declarers.
164	+func documentedBuiltinCapabilities(t *testing.T) ([]string, []string) {
165	+	t.Helper()
166	+
167	+	path := filepath.Join(findAgentDir(t), "capabilities.go")
168	+	fset := token.NewFileSet()
169	+	file, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
170	+	if err != nil {
171	+		t.Fatalf("parser.ParseFile(%s): %v", path, err)
172	+	}
173	+
174	+	for _, decl := range file.Decls {
175	+		gen, ok := decl.(*ast.GenDecl)
176	+		if !ok || gen.Tok != token.TYPE {
177	+			continue
178	+		}
179	+		for _, spec := range gen.Specs {
180	+			typeSpec, ok := spec.(*ast.TypeSpec)
181	+			if !ok || typeSpec.Name.Name != "DeclaredCaps" {
182	+				continue
183	+			}
184	+			doc := typeSpec.Doc
185	+			if doc == nil {
186	+				doc = gen.Doc
187	+			}
188	+			if doc == nil {
189	+				t.Fatal("DeclaredCaps must have a doc comment")
190	+			}
191	+
192	+			var capabilities, refusing []string
193	+			for _, comment := range doc.List {
194	+				line := strings.TrimSpace(strings.TrimPrefix(comment.Text, "//"))
195	+				entry, ok := strings.CutPrefix(line, "- ")
196	+				if !ok {
197	+					continue
198	+				}
199	+				name, mark, _ := strings.Cut(entry, " ")
200	+				if !ast.IsExported(name) || (mark != "" && mark != refusesDeclarersMark) {
201	+					t.Fatalf("invalid capability entry in DeclaredCaps doc: %q", line)
202	+				}
203	+				capabilities = append(capabilities, name)
204	+				if mark != "" {
205	+					refusing = append(refusing, name)
206	+				}
207	+			}
208	+			if len(capabilities) == 0 {
209	+				t.Fatal("DeclaredCaps doc must list built-in capabilities as '- CapabilityName' entries")
210	+			}
211	+			return capabilities, refusing
212	+		}
213	+	}
214	+
215	+	t.Fatal("DeclaredCaps type not found")
216	+	return nil, nil
217	+}
