752	+// agentInterfaceName reports which package-agent interface expr names, if any:
753	+// qualifier.X for files that import the package, or a bare X where qualifier
754	+// is "" (package agent and dot imports).
755	+func agentInterfaceName(expr ast.Expr, qualifier string, interfaces map[string]struct{}) (string, bool) {
756	+	var name string
757	+	switch e := expr.(type) {
758	+	case *ast.SelectorExpr:
759	+		pkg, ok := e.X.(*ast.Ident)
760	+		if !ok || pkg.Name != qualifier {
761	+			return "", false
762	+		}
763	+		name = e.Sel.Name
764	+	case *ast.Ident:
765	+		if qualifier != "" {
766	+			return "", false
767	+		}
768	+		name = e.Name
769	+	default:
770	+		return "", false
771	+	}
772	+	_, ok := interfaces[name]
773	+	return name, ok
774	+}
