776	+// assertedTypes returns every type expression file asserts a value to: the
777	+// X in v.(X) and in each case of a switch v.(type).
778	+func assertedTypes(file *ast.File) []ast.Expr {
779	+	var types []ast.Expr
780	+	ast.Inspect(file, func(n ast.Node) bool {
781	+		switch n := n.(type) {
782	+		case *ast.TypeAssertExpr:
783	+			if n.Type != nil {
784	+				types = append(types, n.Type)
785	+			}
786	+		case *ast.TypeSwitchStmt:
787	+			for _, stmt := range n.Body.List {
788	+				if clause, ok := stmt.(*ast.CaseClause); ok {
789	+					types = append(types, clause.List...)
790	+				}
791	+			}
792	+		}
793	+		return true
794	+	})
795	+	return types
796	+}
